import{_ as o,o as l,c as i,a3 as n,j as t,a,t as r}from"./chunks/framework.D1iekJsc.js";const b=JSON.parse('{"title":"在 MiniTavern 中配置生圖","description":"設置 → 生圖 → 生圖連接：對接本機 A1111 / ComfyUI 或雲端生圖 API。","frontmatter":{"title":"在 MiniTavern 中配置生圖","description":"設置 → 生圖 → 生圖連接：對接本機 A1111 / ComfyUI 或雲端生圖 API。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"在 MiniTavern 中配置生圖 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"設置 → 生圖 → 生圖連接：對接本機 A1111 / ComfyUI 或雲端生圖 API。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen/connect-app"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/local/image-gen/connect-app"}]]},"headers":[],"relativePath":"zh-TW/local/image-gen/connect-app.md","filePath":"zh-TW/local/image-gen/connect-app.md","lastUpdated":1791599898000}'),s={name:"zh-TW/local/image-gen/connect-app.md"},p={tabindex:"0"};function u(d,e,m,h,g,c){return l(),i("div",null,[e[12]||(e[12]=n('<h1 id="在-minitavern-中配置生圖" tabindex="-1">在 MiniTavern 中配置生圖 <a class="header-anchor" href="#在-minitavern-中配置生圖" aria-label="Permalink to &quot;在 MiniTavern 中配置生圖&quot;">​</a></h1><p>本文對應 App 路徑：<strong>設置 → 生圖 → 生圖連接</strong>。</p><p>生圖參數、回覆圖片、關鍵詞觸發見 <a href="/ultra_guides/zh-TW/manual/model-link#生圖連接--回覆圖片--關鍵詞">模型連接 · 生圖</a>。</p><h2 id="新建生圖連接" tabindex="-1">新建生圖連接 <a class="header-anchor" href="#新建生圖連接" aria-label="Permalink to &quot;新建生圖連接&quot;">​</a></h2><ol><li>打開 MiniTavern → 底部 <strong>設置</strong>。</li><li>進入 <strong>生圖</strong> → <strong>生圖連接</strong>。</li><li>點 <strong>新建</strong>。</li><li>選擇 <strong>平臺</strong>，填寫 Base URL / API Key / 模型（按平臺不同）。</li><li><strong>測連</strong> 成功後保存，並設為默認（若列表支持）。</li></ol><h2 id="本機-a1111" tabindex="-1">本機 A1111 <a class="header-anchor" href="#本機-a1111" aria-label="Permalink to &quot;本機 A1111&quot;">​</a></h2><p>先完成 <a href="./a1111">A1111 安裝並開啟 <code>--api --listen</code></a>。</p><table tabindex="0"><thead><tr><th>項</th><th>填寫示例</th></tr></thead><tbody><tr><td>平臺</td><td><strong>A1111(SD WebUI)</strong>（或自定義 A1111 協議）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:7860</code></td></tr><tr><td>API Key</td><td>一般可空；若 WebUI 開了 <code>--api-auth</code> 再按提示填</td></tr><tr><td>模型</td><td>可空或選 WebUI 中的 checkpoint 名（以 App 列表為準）</td></tr></tbody></table><p>將 <code>YOUR_PC_IP</code> 換成電腦局域網 IP。<br><strong>不要</strong>填 <code>http://127.0.0.1:7860</code>（那是電腦自己，不是手機）。</p><p>多張參考圖（角色圖 + 用戶圖，或再加上聊天附圖）需要 WebUI 安裝 ControlNet 擴展。只有一張時不用。步驟見 <a href="./a1111#多張參考圖">安裝 A1111 · 多張參考圖</a>。</p><h2 id="本機-comfyui" tabindex="-1">本機 ComfyUI <a class="header-anchor" href="#本機-comfyui" aria-label="Permalink to &quot;本機 ComfyUI&quot;">​</a></h2><p>先完成 <a href="./comfyui">ComfyUI 安裝並 <code>--listen</code></a>。</p><table tabindex="0"><thead><tr><th>項</th><th>填寫示例</th></tr></thead><tbody><tr><td>平臺</td><td><strong>ComfyUI</strong>（或自定義 ComfyUI 協議）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8188</code>（Desktop 常見 <code>:8000</code>）</td></tr><tr><td>API Key</td><td>一般可空</td></tr><tr><td>模型 / checkpoint</td><td>以 App 拉取到的列表為準；需機器上已有對應文件</td></tr></tbody></table><p>測連失敗時：用手機瀏覽器先打開同一 Base URL，確認不是防火牆或未 listen。</p>',14)),t("p",null,[e[0]||(e[0]=a("默認 workflow 會直接使用多張參考圖，不用在 Comfy 裡先裝插件。要自己接 IPAdapter 或 LoadImage 時，按 ",-1)),e[1]||(e[1]=t("a",{href:"./comfyui#多張參考圖"},"安裝 ComfyUI · 多張參考圖",-1)),e[2]||(e[2]=a(" 在節點裡寫 ",-1)),t("code",null,r(d.reference_image_0),1),e[3]||(e[3]=a(" 起的佔位符，再把 API 格式 JSON 填進這條連接。",-1))]),e[13]||(e[13]=n('<h2 id="雲端生圖-可選" tabindex="-1">雲端生圖（可選） <a class="header-anchor" href="#雲端生圖-可選" aria-label="Permalink to &quot;雲端生圖（可選）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平臺</th><th>何時用</th></tr></thead><tbody><tr><td>ChatGPT(OpenAI)</td><td>官方 Images API（通常付費）</td></tr><tr><td>Gemini(Google)</td><td>Gemini 圖像模型（多數需付費檔，以 Google 定價為準）</td></tr><tr><td>OpenRouter</td><td>路由到支持圖像的上游</td></tr><tr><td>Qwen</td><td>通義萬相 / Qwen-Image（看百鍊是否有免費額度）</td></tr><tr><td>自定義 (OpenAI Images)</td><td>硅基流動、Agnes 等兼容 <code>/images/generations</code> 的網關（圖生圖也走 generations，不是 <code>/images/edits</code>）</td></tr></tbody></table><p>免費雲端與 Key 獲取見 <a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費雲端 · 生圖</a>。</p><h2 id="在聊天裡生圖" tabindex="-1">在聊天裡生圖 <a class="header-anchor" href="#在聊天裡生圖" aria-label="Permalink to &quot;在聊天裡生圖&quot;">​</a></h2><p>配置默認生圖連接後（主聊天模型也需要，用來分析/轉寫提示詞）：</p><table tabindex="0"><thead><tr><th>入口</th><th>說明</th></tr></thead><tbody><tr><td>輸入 <code>/imagine 提示詞</code></td><td>自由生圖。主模型先判斷：這是跟聊天有關的請求（例如「給我一張你的自拍照」→ 用對話 + 角色參考圖），還是無關請求（例如「給我一張小狗的照片」）。可同時在輸入框附圖：主模型會看到這些圖再寫提示詞，生圖時也會當參考；有無附圖都要單獨判斷要不要角色圖/用戶圖。附圖會顯示在生圖氣泡的小預覽裡。張數看 <strong>生圖設置 → 生成數量</strong>。失敗會留下氣泡，可點重試</td></tr><tr><td><code>/imagine scene</code> 或附件 → 根據故事</td><td>按近期對話畫當前這一幕，固定 1 張</td></tr><tr><td><code>/imagine last</code> 或附件 → 根據最後消息</td><td>按最後一條消息來畫，固定 1 張</td></tr><tr><td><code>/imagine background</code> 或附件 → 生成背景圖</td><td>畫環境背景，固定 1 張</td></tr><tr><td>長按氣泡 → 生圖</td><td>按這條氣泡來畫，固定 1 張</td></tr><tr><td>回覆圖片（智能 / 關鍵詞）</td><td>先在生圖設置開啟「回覆圖片」並選擇觸發方式。發普通消息（可附圖）後按當前對話旁路生圖，固定 1 張；附圖作風格參考</td></tr></tbody></table><p>未配置生圖連接時，點附件生圖四種模式或發送 <code>/imagine</code> 會彈出「去設置 / 取消」，不會 Toast，也不會清空輸入框。聊天裡智能 / 關鍵詞自動出圖若無連接則 Toast 提示。生圖設置開啟「回覆圖片」時若無連接也會彈窗，開關保持關閉。</p><p>僅配生圖、未配聊天模型時，需要轉寫的入口會失敗。</p><h2 id="排錯速查" tabindex="-1">排錯速查 <a class="header-anchor" href="#排錯速查" aria-label="Permalink to &quot;排錯速查&quot;">​</a></h2>',9)),t("table",p,[e[11]||(e[11]=t("thead",null,[t("tr",null,[t("th",null,"現象"),t("th",null,"排查")])],-1)),t("tbody",null,[e[6]||(e[6]=t("tr",null,[t("td",null,"測連失敗 / 超時"),t("td",null,[a("電腦服務是否在跑；是否 "),t("code",null,"--api"),a(" / "),t("code",null,"--listen"),a("；IP 與端口是否對；同一 Wi‑Fi")])],-1)),e[7]||(e[7]=t("tr",null,[t("td",null,"本機瀏覽器可以、手機不行"),t("td",null,[a("防火牆；訪客網絡隔離；填了 "),t("code",null,"127.0.0.1")])],-1)),e[8]||(e[8]=t("tr",null,[t("td",null,"A1111 404"),t("td",null,[a("未加 "),t("code",null,"--api"),a("；Base URL 多寫了路徑")])],-1)),e[9]||(e[9]=t("tr",null,[t("td",null,"Comfy 一直轉圈"),t("td",null,"看電腦端 Comfy 隊列與報錯；顯存不足；無可用 checkpoint")],-1)),t("tr",null,[e[5]||(e[5]=t("td",null,"有參考圖但臉不對（Comfy）",-1)),t("td",null,[e[4]||(e[4]=a("默認是把多張參考圖橫向拼成圖生圖。要自己接線，請在 LoadImage 寫 ",-1)),t("code",null,r(d.reference_image_0),1)])]),e[10]||(e[10]=t("tr",null,[t("td",null,[t("code",null,"/imagine"),a(" 失敗氣泡消失")]),t("td",null,"失敗會留下原氣泡並顯示重試；點停止仍會去掉未完成的佔位")],-1))])]),e[14]||(e[14]=t("p",null,[a("更完整的聊天錯誤碼見 "),t("a",{href:"/ultra_guides/zh-TW/manual/errors"},"錯誤排錯"),a("。")],-1))])}const f=o(s,[["render",u]]);export{b as __pageData,f as default};
